(function(){
  'use strict';
  var U=window.BookingUtils,data=U.load();
  if(!data||!data.payment||data.payment.status!=='SUCCESS'){location.href='index.html';return;}

  function text(id,v){var e=document.getElementById(id);if(e)e.textContent=v;}
  text('confirm-train',data.train.name+' · '+data.train.number);
  text('confirm-route',data.train.source+' → '+data.train.destination);
  text('confirm-date',U.dateLabel(data.train.date));
  text('confirm-passengers',data.passengers.length);
  text('confirm-total',U.money(data.fare.total));
  text('confirm-pnr',data.pnr);
  text('confirm-booking',data.bookingId);
  text('confirm-transaction',data.transactionId);
  text('confirm-email',data.contact.email);
  text('confirm-mobile',U.normalizeMobile(data.contact.mobile));
  var emailTemplate=window.DemoEmailTemplate?window.DemoEmailTemplate(data):{body:'Demo booking confirmation for '+data.pnr};
  document.getElementById('email-template').textContent=emailTemplate.body;

  /* Standardized mock IRCTC-style PDF generator.
     The documents are intentionally labelled DEMO / NOT VALID FOR TRAVEL. */
  function ascii(value){
    return String(value==null?'':value)
      .replace(/₹/g,'INR ')
      .replace(/[→➜]/g,'->')
      .replace(/[·•]/g,' - ')
      .replace(/[—–]/g,'-')
      .replace(/×/g,'x')
      .replace(/…/g,'...')
      .replace(/[^\x20-\x7E]/g,'')
      .replace(/\s{2,}/g,' ')
      .trim();
  }
  function escPdf(s){return ascii(s).replace(/[\\()]/g,function(c){return '\\'+c;});}
  function moneyPdf(n){return 'INR '+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});}
  function fit(s,max){s=ascii(s);return s.length>max?s.slice(0,Math.max(0,max-3))+'...':s;}
  function b64Bytes(b64){
    var raw=atob(b64), out=new Uint8Array(raw.length);
    for(var i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);
    return out;
  }
  var IRCTC_LOGO_JPG_B64='';
  function joinBytes(parts){
    var total=0; parts.forEach(function(p){total+=p.length;});
    var out=new Uint8Array(total),at=0;
    parts.forEach(function(p){out.set(p,at);at+=p.length;});
    return out;
  }
  function pdfDocument(drawPages){
    var W=595,H=842,objects={},next=1,font=next++,boldFont=next++,logoObj=next++,pages=next++,catalog=next++,pageIds=[];
    objects[font]=new TextEncoder().encode('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
    objects[boldFont]=new TextEncoder().encode('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
    var logo=b64Bytes(IRCTC_LOGO_JPG_B64);
    var logoDict='<< /Type /XObject /Subtype /Image /Width 1280 /Height 720 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length '+logo.length+' >>\nstream\n';
    objects[logoObj]=joinBytes([new TextEncoder().encode(logoDict),logo,new TextEncoder().encode('\nendstream')]);
    drawPages.forEach(function(content){
      var cid=next++, cbytes=new TextEncoder().encode(content);
      objects[cid]=joinBytes([new TextEncoder().encode('<< /Length '+cbytes.length+' >>\nstream\n'),cbytes,new TextEncoder().encode('\nendstream')]);
      var pid=next++;pageIds.push(pid);
      objects[pid]=new TextEncoder().encode('<< /Type /Page /Parent '+pages+' 0 R /MediaBox [0 0 '+W+' '+H+'] /Resources << /Font << /F1 '+font+' 0 R /F2 '+boldFont+' 0 R >> /XObject << /Im1 '+logoObj+' 0 R >> >> /Contents '+cid+' 0 R >>');
    });
    objects[pages]=new TextEncoder().encode('<< /Type /Pages /Kids ['+pageIds.map(function(x){return x+' 0 R';}).join(' ')+'] /Count '+pageIds.length+' >>');
    objects[catalog]=new TextEncoder().encode('<< /Type /Catalog /Pages '+pages+' 0 R >>');
    var max=next-1,parts=[new TextEncoder().encode('%PDF-1.4\n')],offs=[],pos=parts[0].length;
    for(var i=1;i<=max;i++){
      var head=new TextEncoder().encode(i+' 0 obj\n');
      var tail=new TextEncoder().encode('\nendobj\n');
      offs[i]=pos;
      parts.push(head,objects[i],tail);
      pos+=head.length+objects[i].length+tail.length;
    }
    var xrefPos=pos;
    var xref='xref\n0 '+(max+1)+'\n0000000000 65535 f \n';
    for(i=1;i<=max;i++)xref+=String(offs[i]).padStart(10,'0')+' 00000 n \n';
    xref+='trailer\n<< /Size '+(max+1)+' /Root '+catalog+' 0 R >>\nstartxref\n'+xrefPos+'\n%%EOF';
    parts.push(new TextEncoder().encode(xref));
    return new Blob([joinBytes(parts)],{type:'application/pdf'});
  }
  function textOp(x,y,size,value,bold){
    return 'BT /F'+(bold?'2':'1')+' '+size+' Tf '+x+' '+y+' Td ('+escPdf(value)+') Tj ET\n';
  }
  function rect(x,y,w,h,fill,stroke){
    var s='';
    if(fill)s+='q '+fill+' rg '+x+' '+y+' '+w+' '+h+' re f Q\n';
    if(stroke)s+='q 0.38 0.42 0.50 RG '+x+' '+y+' '+w+' '+h+' re S Q\n';
    return s;
  }
  function line(x1,y1,x2,y2,color,width){
    color=color||'0.72 0.75 0.80'; width=width||1;
    return 'q '+width+' w '+color+' RG '+x1+' '+y1+' m '+x2+' '+y2+' l S Q\n';
  }
  function logoOp(x,y,w,h){return 'q '+w+' 0 0 '+h+' '+x+' '+y+' cm /Im1 Do Q\n';}
  function barcodeOps(value,x,y,w,h){
    value=ascii(value);
    var seed=7; for(var i=0;i<value.length;i++)seed=(seed*31+value.charCodeAt(i))>>>0;
    var ops=rect(x-10,y-10,w+20,h+36,'1 1 1',true);
    var cursor=x;
    ops+='q 0 0 0 rg '+cursor+' '+y+' 2 '+h+' re f Q\n'; cursor+=5;
    while(cursor<x+w-8){
      seed=(seed*1664525+1013904223)>>>0;
      var bw=(seed%4)+1, gap=((seed>>>5)%3)+1;
      if(cursor+bw>x+w-8)break;
      ops+='q 0 0 0 rg '+cursor+' '+y+' '+bw+' '+h+' re f Q'; cursor+=bw+gap;
    }
    ops+='q 0 0 0 rg '+(x+w-6)+' '+y+' 2 '+h+' re f Q\n';
    ops+=textOp(x,y-20,7,'DEMO BARCODE',true);
    ops+=textOp(x+90,y-20,7,fit(value,34),false);
    return ops;
  }
  function header(title,subtitle){
    var c=rect(38,744,519,58,'1 1 1',true);
    c+=logoOp(52,752,62,35);
    c+=textOp(122,778,18,'IRCTC',true);
    c+=textOp(122,761,7,'INDIAN RAILWAY CATERING AND TOURISM CORPORATION',false);
    c+=rect(399,758,142,27,'0.93 0.74 0.24',true);
    c+=textOp(412,768,8,'MOCK AUTHORIZED',true);
    c+=line(38,744,557,744,'0.05 0.17 0.30',2);
    c+=textOp(54,718,15,title,true);
    c+=textOp(402,719,7,'DEMONSTRATION ONLY',true);
    c+=textOp(54,704,7,subtitle,false);
    return c;
  }
  function labelValue(label,value,x,y,max){
    return textOp(x,y,7,label.toUpperCase(),false)+textOp(x,y-15,10,fit(value,max||28),true);
  }
  function passengerRows(c,y,limit){
    data.passengers.forEach(function(p,idx){
      if(y<limit)return;
      c+=rect(46,y-10,503,31,idx%2?'0.97 0.98 0.99':'1 1 1',true);
      c+=textOp(55,y,8,String(idx+1),true);
      c+=textOp(75,y,8,fit(p.name||'Passenger '+(idx+1),24),true);
      c+=textOp(245,y,7,fit((p.age||'-')+' / '+(p.gender||'-'),16),false);
      c+=textOp(320,y,7,fit(p.berthPreference||'No preference',22),false);
      c+=textOp(445,y,7,fit(p.idType||'ID',10),false);
      y-=36;
    });
    return c;
  }

  function ticketPdf(){
    var pages=[],c=header('RAILWAY E-TICKET','MOCK ELECTRONIC RESERVATION TICKET'),y=675;
    c+=rect(46,y-48,503,48,'0.05 0.17 0.30',false);
    c+=textOp(58,y-19,9,'TRAIN',false)+textOp(58,y-36,14,fit(data.train.number+' - '+data.train.name,45),true);
    c+=textOp(375,y-19,9,'CLASS',false)+textOp(375,y-36,12,U.classLabel(data.train.class),true); y-=68;
    c+=labelValue('From',data.train.source+' ('+data.train.sourceCode+')',54,y,30);
    c+=labelValue('Departure',data.train.departure,205,y,16);
    c+=labelValue('Date',U.dateLabel(data.train.date),310,y,18);
    c+=labelValue('To',data.train.destination+' ('+data.train.destinationCode+')',405,y,27); y-=58;
    c+=line(54,y,541,y,'0.05 0.17 0.30',1.5); y-=20;
    c+=textOp(54,y,10,'JOURNEY DETAILS',true); y-=22;
    c+=labelValue('Arrival',data.train.arrival,54,y,16);
    c+=labelValue('Duration',data.train.duration,180,y,18);
    c+=labelValue('Passengers',String(data.passengers.length),320,y,12);
    c+=labelValue('Status','PAID - DEMO',420,y,14); y-=62;
    c+=textOp(54,y,10,'PASSENGERS',true); y-=20;
    c+=textOp(55,y,7,'NO.',true)+textOp(75,y,7,'NAME',true)+textOp(245,y,7,'AGE / GENDER',true)+textOp(320,y,7,'BERTH',true)+textOp(445,y,7,'ID',true); y-=10;
    for(var idx=0;idx<data.passengers.length;idx++){
      if(y<390){pages.push(c);c=header('RAILWAY E-TICKET - CONTINUED','MOCK ELECTRONIC RESERVATION TICKET');y=690;}
      var p=data.passengers[idx];
      c+=rect(46,y-10,503,31,idx%2?'0.97 0.98 0.99':'1 1 1',true);
      c+=textOp(55,y,8,String(idx+1),true)+textOp(75,y,8,fit(p.name||'Passenger '+(idx+1),24),true);
      c+=textOp(245,y,7,fit((p.age||'-')+' / '+(p.gender||'-'),16),false);
      c+=textOp(320,y,7,fit(p.berthPreference||'No preference',20),false);
      c+=textOp(445,y,7,fit(p.idType||'ID',10),false); y-=36;
    }
    // Keep fare details on a dedicated page so the breakdown can never
    // collide with passenger rows or the barcode on long bookings.
    pages.push(c);
    c=header('RAILWAY E-TICKET - FARE','MOCK ELECTRONIC RESERVATION TICKET'); y=690;
    c+=textOp(54,y,10,'FARE DETAILS',true); y-=26;
    c+=rect(46,y-108,503,122,'0.97 0.98 0.99',true);
    [['Railway fare',data.fare.baseFare],['Reservation / booking charge',data.fare.reservationCharges],['GST on booking charge',data.fare.taxes],['Other applicable charges',data.fare.otherCharges]].forEach(function(row,ix){
      var ry=y-(ix*21);
      c+=textOp(60,ry,8,row[0],false)+textOp(438,ry,8,moneyPdf(row[1]),false);
    });
    c+=line(58,y-84,537,y-84,'0.45 0.48 0.54',1);
    c+=textOp(60,y-101,9,'TOTAL PAID - DEMO',true)+textOp(430,y-101,9,moneyPdf(data.fare.total),true);
    c+=textOp(54,y-139,7,'Fare snapshot: railway fare, booking charge, GST and other applicable charges are shown separately.',false);
    c+=barcodeOps(data.pnr+'-'+data.train.number+'-'+String(data.train.date||'DATE').replace(/-/g,''),166,y-222,263,48);
    c+=textOp(54,44,7,'DEMO / NOT VALID FOR TRAVEL - This document is a mock representation only.',true);
    c+=textOp(54,31,7,'Generated locally. PNR, authorization, barcode and payment status are demonstration values.',false);
    pages.push(c); return pdfDocument(pages);
  }

  function invoicePdf(){
    var pages=[],c=header('BOOKING INVOICE','MOCK RAILWAY BOOKING INVOICE'),y=675;
    c+=textOp(54,y,10,'BOOKING INFORMATION',true); y-=22;
    c+=labelValue('Demo PNR',data.pnr,54,y,18);
    c+=labelValue('Booking ID',data.bookingId,190,y,24);
    c+=labelValue('Transaction ID',data.transactionId,370,y,25); y-=58;
    c+=textOp(54,y,10,'JOURNEY INFORMATION',true); y-=22;
    c+=labelValue('Train',data.train.number+' - '+data.train.name,54,y,44);
    c+=labelValue('Class',U.classLabel(data.train.class),390,y,16); y-=48;
    c+=labelValue('From',data.train.source,54,y,27);
    c+=labelValue('Departure',data.train.departure,235,y,15);
    c+=labelValue('To',data.train.destination,345,y,27); y-=48;
    c+=labelValue('Arrival',data.train.arrival,54,y,15);
    c+=labelValue('Journey date',U.dateLabel(data.train.date),180,y,18);
    c+=labelValue('Passengers',String(data.passengers.length),390,y,12); y-=56;
    c+=textOp(54,y,10,'PASSENGER INFORMATION',true); y-=20;
    data.passengers.forEach(function(p,idx){
      if(y<420){pages.push(c);c=header('BOOKING INVOICE - CONTINUED','MOCK RAILWAY BOOKING INVOICE');y=690;}
      c+=rect(46,y-10,503,31,idx%2?'0.97 0.98 0.99':'1 1 1',true);
      c+=textOp(55,y,8,String(idx+1),true)+textOp(75,y,8,fit(p.name||'Passenger '+(idx+1),30),true);
      c+=textOp(300,y,7,fit((p.age||'-')+' / '+(p.gender||'-'),18),false);
      c+=textOp(380,y,7,fit(p.idType||'ID',12),false);
      c+=textOp(435,y,7,fit(p.berthPreference||'No preference',18),false); y-=36;
    });
    if(y<330){pages.push(c);c=header('BOOKING INVOICE - FARE','MOCK RAILWAY BOOKING INVOICE');y=690;}
    y-=8;c+=textOp(54,y,10,'FARE BREAKDOWN',true); y-=26;
    c+=rect(46,y-116,503,130,'0.97 0.98 0.99',true);
    [['Base railway fare',data.fare.baseFare],['Reservation / booking charge',data.fare.reservationCharges],['GST on booking charge',data.fare.taxes],['Other applicable charges',data.fare.otherCharges]].forEach(function(row,ix){
      var ry=y-(ix*22);
      c+=textOp(60,ry,8,row[0],false)+textOp(438,ry,8,moneyPdf(row[1]),false);
    });
    c+=line(58,y-88,537,y-88,'0.45 0.48 0.54',1);
    c+=textOp(60,y-106,9,'TOTAL PAID - DEMO',true)+textOp(430,y-106,9,moneyPdf(data.fare.total),true);
    c+=textOp(54,y-146,7,'Fare snapshot: railway fare, booking charge, GST and other applicable charges are shown separately.',false);
    c+=textOp(54,64,7,'DEMO / NOT AN OFFICIAL IRCTC DOCUMENT. No real reservation or payment was processed.',true);
    c+=textOp(54,50,7,'Amounts shown are for demonstration purposes only.',false);
    pages.push(c);return pdfDocument(pages);
  }

  function blobToFile(blob,name){return new File([blob],name,{type:'application/pdf'});}
  function makeFiles(){return [blobToFile(invoicePdf(),'IRCTC-Demo-Invoice-'+data.pnr+'.pdf'),blobToFile(ticketPdf(),'IRCTC-Demo-Ticket-'+data.pnr+'.pdf')];}
  function download(blob,name){var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(a.href);},1000);}
  var bill=document.getElementById('download-bill'),ticket=document.getElementById('download-ticket');
  bill.onclick=function(){download(invoicePdf(),'IRCTC-Demo-Invoice-'+data.pnr+'.pdf');};
  ticket.onclick=function(){download(ticketPdf(),'IRCTC-Demo-Ticket-'+data.pnr+'.pdf');};
  function setDelivery(msg){var e=document.getElementById('delivery-status');if(e)e.textContent=msg;}
  function shareFiles(){
    var files=makeFiles();
    if(navigator.share&&navigator.canShare&&navigator.canShare({files:files})){
      navigator.share({title:'IRCTC Demo Booking '+data.pnr,text:'Demo invoice and ticket for PNR '+data.pnr,files:files}).then(function(){setDelivery('Invoice and ticket shared through your device share sheet.');}).catch(function(e){if(e.name!=='AbortError')setDelivery('Sharing was cancelled or unavailable.');});
    }else setDelivery('Your browser cannot attach generated files directly. Download both PDFs and attach them to your email or messaging app.');
  }
  document.getElementById('share-files').onclick=shareFiles;
  document.getElementById('send-email').onclick=function(){
    var files=makeFiles();
    if(navigator.share&&navigator.canShare&&navigator.canShare({files:files})) return shareFiles();
    location.href='mailto:'+encodeURIComponent(data.contact.email)+'?subject='+encodeURIComponent('Your Railway Booking Confirmation - Demo PNR '+data.pnr)+'&body='+encodeURIComponent(emailTemplate.body+'\n\nThe generated invoice and ticket PDFs are available for download on the confirmation page.');
    setDelivery('Your email app was opened with the confirmation addressed to '+data.contact.email+'. Attach the downloaded PDFs to send them.');
  };
  document.getElementById('send-mobile').onclick=function(){
    var files=makeFiles();
    if(navigator.share&&navigator.canShare&&navigator.canShare({files:files})) return shareFiles();
    location.href='sms:+91'+U.normalizeMobile(data.contact.mobile)+'?body='+encodeURIComponent('Your demo railway booking '+data.pnr+' is confirmed. The invoice and ticket PDFs are ready on the confirmation page.');
    setDelivery('Your messaging app was opened for +91 '+U.normalizeMobile(data.contact.mobile)+'. Attach/share the downloaded PDFs from the confirmation page.');
  };
  document.getElementById('new-booking').onclick=function(){U.clear();location.href='index.html';};
})();
